INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20OQEW1', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'The system of equations $7x + 3y = k$ and $21x + 9y = 54$ has infinitely many solutions, where $k$ is a constant. What is the value of $k$?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$18$"},{"key":"C","text":"$27$"},{"key":"D","text":"$54$"}]$lyceon_json$::jsonb, 'B', NULL, E'For infinitely many solutions, the two equations must be scalar multiples of each other. The second equation $21x + 9y = 54$ equals $3(7x + 3y) = 54$, so $7x + 3y = 18$. Therefore $k$ must equal $18$. Choosing $54$ results from setting $k$ equal to the constant on the right side of the second equation without dividing by the scale factor $3$. Choosing $27$ comes from an arithmetic error such as dividing $54$ by $2$ instead of $3$. Choosing $9$ results from dividing $54$ by $6$ or confusing the coefficient relationship.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21V2LB4', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A researcher surveys a random sample of 150 voters in a city and finds that 63 of them support a proposed parks initiative. The margin of error for the survey is 7 percentage points. Which of the following is the best estimate of the range of the percentage of all voters in the city who support the initiative?', NULL, $lyceon_json$[{"key":"A","text":"35% to 49%"},{"key":"B","text":"42% to 49%"},{"key":"C","text":"35% to 56%"},{"key":"D","text":"37% to 47%"}]$lyceon_json$::jsonb, 'A', NULL, E'The sample proportion is $\\frac{63}{150} = 0.42$, or 42%. With a margin of error of 7 percentage points, the plausible range is $42\\% - 7\\% = 35\\%$ to $42\\% + 7\\% = 49\\%$. The range 42% to 49% only adds the margin of error above the estimate, omitting the lower bound. The range 35% to 56% incorrectly doubles the margin of error on the upper side ($42 + 14 = 56$). The range 37% to 47% uses a margin of error of 5 percentage points instead of 7.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM229WHEY', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What value of $x$ satisfies the equation $4x + 11 = 35$?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$-6$"},{"key":"C","text":"$24$"},{"key":"D","text":"$\\frac{46}{4}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Subtracting $11$ from both sides gives $4x = 24$. Dividing both sides by $4$ yields $x = 6$. The distractor $-6$ results from a sign error when isolating $x$, incorrectly negating the result. The distractor $24$ comes from stopping after computing $4x = 24$ without dividing by $4$. The distractor $\\frac{46}{4}$ results from adding $11$ to $35$ instead of subtracting, then dividing by $4$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23WBBC9', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A bakery charges a \\$19 delivery fee plus \\$4 per cupcake. A customer wants to spend no more than \\$83 total. What is the maximum number of whole cupcakes the customer can order?', NULL, $lyceon_json$[{"key":"A","text":"$14$"},{"key":"B","text":"$15$"},{"key":"C","text":"$16$"},{"key":"D","text":"$17$"}]$lyceon_json$::jsonb, 'C', NULL, E'The total cost for $n$ cupcakes is $19 + 4n$. Setting up the inequality $19 + 4n \\leq 83$ and subtracting $19$ from both sides gives $4n \\leq 64$, so $n \\leq 16$. The maximum whole number of cupcakes is $16$. Choosing $17$ results from misreading the inequality or an arithmetic error such as subtracting $19$ from $83$ and getting $68$ instead of $64$. Choosing $15$ comes from rounding down unnecessarily when $16$ is already a whole number satisfying the inequality. Choosing $14$ results from a subtraction slip such as computing $83 - 19 = 60$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24SQ1X4', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In a right triangle, one of the acute angles has measure $\\theta$. If $\\sin(\\theta) = \\frac{7}{25}$, what is the value of $\\cos(\\theta)$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{7}{24}$"},{"key":"B","text":"$\\frac{18}{25}$"},{"key":"C","text":"$\\frac{24}{25}$"},{"key":"D","text":"$\\frac{24}{7}$"}]$lyceon_json$::jsonb, 'C', NULL, E'Since $\\sin(\\theta) = \\frac{7}{25}$, the opposite side is $7$ and the hypotenuse is $25$. Using the Pythagorean theorem, the adjacent side is $\\sqrt{25^2 - 7^2} = \\sqrt{625 - 49} = \\sqrt{576} = 24$. Therefore $\\cos(\\theta) = \\frac{24}{25}$. The value $\\frac{7}{24}$ confuses cosine with tangent ($\\frac{\\text{opposite}}{\\text{adjacent}}$). The value $\\frac{18}{25}$ results from subtracting $7$ from $25$ instead of using the Pythagorean theorem. The value $\\frac{24}{7}$ is $\\tan(\\theta)$, not $\\cos(\\theta)$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24TXPGG', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'grid_in', E'A set of 6 data points has coordinates $(1, 9)$, $(2, 14)$, $(3, 18)$, $(5, 29)$, $(7, 37)$, and $(8, 43)$. A linear model $y = ax + b$ is fit using the points $(1, 9)$ and $(8, 43)$. What is the value of $a + b$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '9', ARRAY['9'], E'The slope is $a = \\frac{43 - 9}{8 - 1} = \\frac{34}{7}$. Using the point $(1, 9)$: $9 = \\frac{34}{7}(1) + b$, so $b = 9 - \\frac{34}{7} = \\frac{63 - 34}{7} = \\frac{29}{7}$. Therefore $a + b = \\frac{34}{7} + \\frac{29}{7} = \\frac{63}{7} = 9$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM254VUZ0', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'grid_in', E'A craft store sells two types of gift baskets. A small basket contains $3$ candles and $5$ soaps, and a large basket contains $7$ candles and $2$ soaps. On one day the store used exactly $37$ candles and $23$ soaps to assemble baskets of these two types only. How many large baskets were assembled that day?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'Let $s$ represent the number of small baskets and $g$ the number of large baskets. The candle constraint gives $3s + 7g = 37$ and the soap constraint gives $5s + 2g = 23$. Multiply the first equation by $5$ and the second by $3$: $15s + 35g = 185$ and $15s + 6g = 69$. Subtracting the second from the first yields $29g = 116$, so $g = 4$. Then $5s + 2(4) = 23$ gives $5s = 15$, so $s = 3$. Verification: $3(3) + 7(4) = 9 + 28 = 37$ candles and $5(3) + 2(4) = 15 + 8 = 23$ soaps, both correct.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM269UE5V', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A jar contains 5 red candies, 8 yellow candies, and 7 green candies. If one candy is selected at random, what is the probability that it is red?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{5}{20}$"},{"key":"B","text":"$\\frac{5}{15}$"},{"key":"C","text":"$\\frac{8}{20}$"},{"key":"D","text":"$\\frac{7}{20}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total number of candies is $5 + 8 + 7 = 20$. The probability of selecting a red candy is the number of red candies divided by the total: $\\frac{5}{20}$. The value $\\frac{5}{15}$ divides by only the non-red total instead of the full count, a concept gap about how probability of a single event is computed. The value $\\frac{8}{20}$ incorrectly uses the count of yellow candies instead of red. The value $\\frac{7}{20}$ incorrectly uses the count of green candies instead of red.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26FBLXI', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'grid_in', E'A teacher records quiz scores for 7 students: 62, 71, 74, 78, 83, 89, and 95. If a new student scores 86 on the quiz, what is the median quiz score for all 8 students?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '80.5', ARRAY['161/2', '80.5'], E'The original 7 scores in order are 62, 71, 74, 78, 83, 89, 95. Adding the score 86 gives the sorted list: 62, 71, 74, 78, 83, 86, 89, 95. With 8 values, the median is the average of the 4th and 5th values: $\\frac{78 + 83}{2} = \\frac{161}{2} = 80.5$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26WSYFD', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'grid_in', E'In right triangle $JKL$, angle $K$ is the right angle. If $JK = 15$ and $\\tan(J) = \\frac{4}{3}$, what is the length of the hypotenuse $JL$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '25', ARRAY['25'], E'In right triangle $JKL$ with the right angle at $K$, side $KL$ is opposite angle $J$ and side $JK$ is adjacent to angle $J$. Since $\\tan(J) = \\frac{\\text{opposite}}{\\text{adjacent}} = \\frac{KL}{JK} = \\frac{KL}{15} = \\frac{4}{3}$, we get $KL = 15 \\times \\frac{4}{3} = 20$. The hypotenuse $JL = \\sqrt{JK^2 + KL^2} = \\sqrt{15^2 + 20^2} = \\sqrt{225 + 400} = \\sqrt{625} = 25$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2756XZJ', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'grid_in', E'$$2x + 3y = 19$$ $$4x - y = 3$$ What is the value of $y$ in the solution to the system of equations above?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'From the second equation, $y = 4x - 3$. Substituting into the first equation: $2x + 3(4x - 3) = 19$, which simplifies to $2x + 12x - 9 = 19$, so $14x = 28$ and $x = 2$. Then $y = 4(2) - 3 = 5$. Verification: $2(2) + 3(5) = 4 + 15 = 19$ and $4(2) - 5 = 3$, both correct.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27QW54L', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A recipe calls for $\\frac{7}{4}$ cups of rice to serve 5 people. If the recipe is scaled proportionally, how many cups of rice are needed to serve 18 people?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{63}{10}$"},{"key":"B","text":"$\\frac{63}{20}$"},{"key":"C","text":"$\\frac{90}{7}$"},{"key":"D","text":"$\\frac{35}{72}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The proportion is $\\frac{7/4}{5} = \\frac{x}{18}$, so $x = \\frac{7}{4} \\times \\frac{18}{5} = \\frac{126}{20} = \\frac{63}{10}$. The answer $\\frac{63}{20}$ results from halving the numerator by mistake, equivalent to scaling to only 9 people instead of 18. The answer $\\frac{90}{7}$ comes from inverting the proportion and computing $\\frac{5 \\times 18}{7}$, ignoring the denominator of 4. The answer $\\frac{35}{72}$ comes from multiplying $\\frac{7}{4}$ by $\\frac{5}{18}$ instead of $\\frac{18}{5}$, reversing the scaling direction.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27T8R8P', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A survey of 200 commuters classified each by transportation mode and whether they arrive on time. Of the 200 commuters, 74 drive alone, 58 carpool, and 68 use public transit. Among those who drive alone, 61 arrive on time. Among those who carpool, 43 arrive on time. Among those who use public transit, 49 arrive on time. Given that a randomly selected commuter arrives on time, what is the probability that the commuter uses public transit?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{49}{68}$"},{"key":"B","text":"$\\frac{49}{153}$"},{"key":"C","text":"$\\frac{68}{200}$"},{"key":"D","text":"$\\frac{49}{200}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The total number who arrive on time is $61 + 43 + 49 = 153$. Among those 153 on-time commuters, 49 use public transit. The conditional probability is $\\frac{49}{153}$. The value $\\frac{49}{68}$ divides by the total number of public transit users rather than by all on-time commuters, computing $P(\\text{on time} \\mid \\text{public transit})$ instead of the requested conditional probability. The value $\\frac{68}{200}$ gives the unconditional probability of using public transit, ignoring the on-time condition. The value $\\frac{49}{200}$ divides by the total number of commuters rather than conditioning on on-time arrival.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27UKCZZ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $f(x) = 3x^2 - 18x + 31$ can be rewritten in vertex form as $f(x) = 3(x - h)^2 + k$. What is the value of $k$?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$31$"},{"key":"C","text":"$-27$"},{"key":"D","text":"$22$"}]$lyceon_json$::jsonb, 'A', NULL, E'To convert to vertex form, factor out the leading coefficient from the first two terms: $f(x) = 3(x^2 - 6x) + 31$. Completing the square inside the parentheses: $x^2 - 6x = (x - 3)^2 - 9$. Substituting back: $f(x) = 3((x - 3)^2 - 9) + 31 = 3(x - 3)^2 - 27 + 31 = 3(x - 3)^2 + 4$. So $k = 4$. The distractor $31$ comes from using the original constant term without completing the square. The distractor $-27$ comes from computing $3 \\cdot (-9) = -27$ but forgetting to add the original constant $31$. The distractor $22$ results from an arithmetic slip when combining $-27 + 31$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28PSJPS', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'grid_in', E'Triangle $ABC$ is similar to triangle $DEF$. The side lengths of triangle $ABC$ are $7$, $11$, and $13$. If the longest side of triangle $DEF$ is $39$, what is the perimeter of triangle $DEF$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '93', ARRAY['93'], E'Since triangle $ABC$ is similar to triangle $DEF$, their corresponding sides are proportional. The longest side of triangle $ABC$ is $13$, and the longest side of triangle $DEF$ is $39$, so the scale factor is $\\frac{39}{13} = 3$. The perimeter of triangle $ABC$ is $7 + 11 + 13 = 31$. Multiplying by the scale factor gives the perimeter of triangle $DEF$ as $31 \\times 3 = 93$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28UKDX4', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A linear function $h$ satisfies $h(3) = 11$ and $h(8) = 31$. What is the value of $h(0)$?', NULL, $lyceon_json$[{"key":"A","text":"$-1$"},{"key":"B","text":"$4$"},{"key":"C","text":"$-7$"},{"key":"D","text":"$2$"}]$lyceon_json$::jsonb, 'A', NULL, E'The rate of change is $\\frac{31 - 11}{8 - 3} = \\frac{20}{5} = 4$. So $h(x) = 4x + b$. Using $h(3) = 11$: $12 + b = 11$, giving $b = -1$. Therefore $h(0) = -1$. The distractor $4$ confuses the slope with the $y$-intercept, a concept gap about which quantity represents the output at zero. The distractor $-7$ comes from an arithmetic slip such as subtracting the slope again from the intercept: $-1 - 4 \\cdot \\frac{3}{2}$, or a similar miscalculation. The distractor $2$ results from a sign error when solving $12 + b = 11$, incorrectly getting $b = 2$ instead of $b = -1$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM299BBB8', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'Line $\\ell$ passes through the points $(1, 9)$ and $(4, -6)$. What is the $y$-intercept of line $\\ell$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '14', ARRAY['14'], E'The slope of the line is $m = \\frac{-6 - 9}{4 - 1} = \\frac{-15}{3} = -5$. Using point-slope form with the point $(1, 9)$: $y - 9 = -5(x - 1)$, which gives $y = -5x + 5 + 9 = -5x + 14$. The $y$-intercept is $14$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2B3TDJ5', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'What is the radius of the circle defined by the equation $x^2 + y^2 + 10x - 8y + 16 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$5$"},{"key":"C","text":"$9$"},{"key":"D","text":"$25$"}]$lyceon_json$::jsonb, 'B', NULL, E'Rewrite the equation by completing the square. Group terms: $(x^2 + 10x) + (y^2 - 8y) = -16$. Complete the square for $x$: $x^2 + 10x + 25 = (x + 5)^2$. Complete the square for $y$: $y^2 - 8y + 16 = (y - 4)^2$. Adding $25$ and $16$ to both sides gives $(x + 5)^2 + (y - 4)^2 = -16 + 25 + 16 = 25$. The standard form is $(x + 5)^2 + (y - 4)^2 = 25$, so $r^2 = 25$ and $r = 5$. The value $3$ results from an arithmetic error when adding the constants on the right side, such as computing $-16 + 25 + 16 = 9$ and then $\\sqrt{9} = 3$. The value $9$ comes from adding the absolute values of the half-coefficients ($5 + 4 = 9$) rather than completing the square properly. The value $25$ is $r^2$, the result of failing to take the square root in the final step.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BDTXKY', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'A linear function $f$ satisfies $f(-2) = 23$ and $f(5) = -19$. What is the value of $f(11)$?', NULL, $lyceon_json$[{"key":"A","text":"$-55$"},{"key":"B","text":"$-61$"},{"key":"C","text":"$-49$"},{"key":"D","text":"$-31$"}]$lyceon_json$::jsonb, 'A', NULL, E'The slope is $\\frac{-19 - 23}{5 - (-2)} = \\frac{-42}{7} = -6$. Using the point $(5, -19)$: $f(x) = -6(x - 5) + (-19) = -6x + 30 - 19 = -6x + 11$. Evaluating at $x = 11$: $f(11) = -6(11) + 11 = -66 + 11 = -55$. The distractor $-61$ comes from an arithmetic slip, such as using $5$ instead of $11$ as the $y$-intercept: $-66 + 5 = -61$. The distractor $-49$ arises from partial reasoning where the student computes the change from $x = 5$ to $x = 11$ as $-6 \\times 5 = -30$ instead of $-6 \\times 6 = -36$, getting $-19 - 30 = -49$. The distractor $-31$ results from a sign error when computing the intercept.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C91R7H', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a diameter of $18$. What is the area of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$18\\pi$"},{"key":"B","text":"$36\\pi$"},{"key":"C","text":"$81\\pi$"},{"key":"D","text":"$324\\pi$"}]$lyceon_json$::jsonb, 'C', NULL, E'The radius is half the diameter: $r = \\frac{18}{2} = 9$. The area is $\\pi r^2 = \\pi(9)^2 = 81\\pi$. The value $18\\pi$ results from using the diameter as the radius in the circumference formula ($\\pi d$). The value $36\\pi$ comes from using half the diameter but computing $\\pi(2r)^2 / \\pi r^2$ incorrectly, or confusing with $\\pi(6)^2$. The value $324\\pi$ results from using the diameter ($18$) instead of the radius in the area formula: $\\pi(18)^2$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CXF5SN', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'grid_in', E'A car travels 203 miles using 8.12 gallons of fuel. A truck travels 171 miles using 9.5 gallons of fuel. What is the positive difference, in miles per gallon, between the fuel efficiency of the car and the fuel efficiency of the truck? Round your answer to the nearest whole number.', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'The car''s fuel efficiency is $\\frac{203}{8.12} = 25$ miles per gallon. The truck''s fuel efficiency is $\\frac{171}{9.5} = 18$ miles per gallon. The positive difference is $25 - 18 = 7$ miles per gallon.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2D4S5S5', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A researcher collects data on the number of hours studied ($x$) and test scores ($y$) for 10 students. The line of best fit is $y = 4.7x + 53$. One student studied for 6 hours and scored 79. What is the residual for this student?', NULL, $lyceon_json$[{"key":"A","text":"$-2.2$"},{"key":"B","text":"$2.2$"},{"key":"C","text":"$-81.2$"},{"key":"D","text":"$50.8$"}]$lyceon_json$::jsonb, 'A', NULL, E'The predicted value is $y = 4.7(6) + 53 = 28.2 + 53 = 81.2$. The residual is the actual value minus the predicted value: $79 - 81.2 = -2.2$. The answer $2.2$ reverses the subtraction order (predicted minus actual) resulting in a sign error. The answer $-81.2$ confuses the residual with the negative of the predicted value itself. The answer $50.8$ subtracts only the slope term from the score ($79 - 28.2$), omitting the intercept in the predicted value calculation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EY9MNC', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'Two independent random samples are taken from the same large population to estimate the proportion $p$ of residents who compost food waste. Sample 1 has 400 residents and produces an estimate of $\\hat{p}_1 = 0.31$ with a margin of error of 4.6 percentage points. Sample 2 has 1,600 residents and produces an estimate of $\\hat{p}_2 = 0.27$ with a margin of error of 2.3 percentage points. Which of the following statements is best supported by the information given?', NULL, $lyceon_json$[{"key":"A","text":"Because Sample 2 has a larger sample size, its confidence interval has a smaller margin of error, providing a more precise estimate of the true proportion than Sample 1's interval."},{"key":"B","text":"Sample 1 is more likely to be biased than Sample 2 because its margin of error is larger."},{"key":"C","text":"The true proportion $p$ is more likely to be closer to 0.27 than to 0.31 because Sample 2 has a smaller margin of error."},{"key":"D","text":"The confidence intervals from the two samples must overlap because they are drawn from the same population."}]$lyceon_json$::jsonb, 'A', NULL, E'A larger random sample produces a smaller margin of error, resulting in a narrower confidence interval that gives a more precise estimate of the true population proportion. The data confirm this: Sample 2 (1,600 residents) has a margin of error of 2.3 percentage points, less than half the 4.6-percentage-point margin of Sample 1 (400 residents). The claim that Sample 1 is more likely to be biased confuses precision (margin of error) with accuracy (bias); a larger margin of error reflects less precision from a smaller sample, not necessarily bias in the sampling method. Saying the true proportion is more likely to be closer to 0.27 conflates a point estimate with a probability statement about the parameter; both intervals are valid estimates and neither point estimate is guaranteed to be closer to $p$. The claim that the two intervals must overlap is not guaranteed by sampling theory; independent samples from the same population can produce non-overlapping confidence intervals, especially when the estimates differ sufficiently relative to their margins.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FAMR7Z', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'Researchers want to test whether a new classroom seating arrangement improves reading comprehension scores among 4th graders. They randomly select 16 classrooms in a school district, then randomly assign 8 classrooms to use the new arrangement and 8 classrooms to keep the traditional arrangement for one semester. At the end of the semester, the mean reading comprehension score is 6.7 points higher in the new-arrangement classrooms, and this difference is statistically significant at $p < 0.05$. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The new seating arrangement causes improved reading comprehension scores among all 4th graders nationwide."},{"key":"B","text":"The new seating arrangement is associated with higher reading comprehension scores, but no causal conclusion can be drawn because individual students were not randomly assigned."},{"key":"C","text":"The new seating arrangement causes improved reading comprehension scores among 4th graders in the school district."},{"key":"D","text":"The new seating arrangement has no meaningful effect on reading comprehension because the 6.7-point difference is too small to matter."}]$lyceon_json$::jsonb, 'C', NULL, E'Classrooms were randomly selected from the district (supporting generalization to the district) and randomly assigned to treatments (supporting a causal conclusion). A statistically significant result at $p < 0.05$ means the observed difference is unlikely due to chance alone. Therefore, a causal conclusion generalizable to 4th graders in the school district is appropriate. The claim about all 4th graders nationwide overgeneralizes beyond the population from which classrooms were sampled. The claim that no causal conclusion can be drawn because individual students were not randomly assigned misapplies the principle; cluster-level random assignment (classrooms) is a valid experimental design that supports causal inference. The claim that 6.7 points is too small to matter confuses statistical significance with practical significance and dismisses a statistically significant result without justification.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GB2C5I', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which value of $x$ satisfies the inequality $5x + 3 > 28$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$4$"},{"key":"C","text":"$5$"},{"key":"D","text":"$6$"}]$lyceon_json$::jsonb, 'D', NULL, E'Subtracting $3$ from both sides gives $5x > 25$, and dividing both sides by $5$ gives $x > 5$. The only value greater than $5$ among the choices is $6$. The value $5$ fails because the inequality is strict (not $\\geq$), so $x = 5$ yields $5(5) + 3 = 28$, which is not greater than $28$. The values $3$ and $4$ are both less than $5$ and produce results well below $28$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GED9PP', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A university researcher finds that students who attend optional review sessions score, on average, 13 points higher on the final exam than students who do not attend. Students were free to choose whether to attend the review sessions. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Attending review sessions causes higher exam scores."},{"key":"B","text":"There is an association between attending review sessions and higher exam scores, but a causal conclusion is not warranted."},{"key":"C","text":"Students who attend review sessions are inherently more intelligent than those who do not."},{"key":"D","text":"The 13-point difference is not statistically significant because the study lacked random assignment."}]$lyceon_json$::jsonb, 'B', NULL, E'Because students self-selected into review sessions (no random assignment of treatment), this is an observational study. Observational studies can establish association but not causation, since confounding variables (e.g., motivation, prior preparation) may explain the difference. Claiming that attending sessions causes higher scores draws a causal conclusion that is not supported without random assignment. Claiming students who attend are inherently more intelligent introduces an unsupported assumption about a specific confounding variable. Stating the difference is not statistically significant because the study lacked random assignment conflates causal inference (which requires random assignment) with statistical significance (which depends on sample size and variability, not study design).', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GICO0Q', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'mcq', E'$$3x + y = 19$$ $$x - y = 5$$ What is the value of $x$ in the solution to the system of equations above?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$5$"},{"key":"C","text":"$6$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'C', NULL, E'Adding the two equations eliminates $y$: $(3x + y) + (x - y) = 19 + 5$, which gives $4x = 24$, so $x = 6$. Choosing $5$ results from solving for $y$ instead, since $y = 1$ when $x = 6$, and confusing which variable was requested. Choosing $7$ comes from a sign error when combining the $y$ terms, such as subtracting the equations instead of adding. Choosing $4$ results from a division slip such as computing $24 \\div 6$ instead of $24 \\div 4$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HGWSQN', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $f$ is defined by $f(x) = -3x^2 + 42x - 143$. Which of the following correctly describes the range of $f$?', NULL, $lyceon_json$[{"key":"A","text":"$f(x) \\leq 4$"},{"key":"B","text":"$f(x) \\geq 4$"},{"key":"C","text":"$f(x) \\leq -143$"},{"key":"D","text":"$f(x) \\leq 7$"}]$lyceon_json$::jsonb, 'A', NULL, E'Since the leading coefficient is $-3 < 0$, the parabola opens downward, meaning $f$ has a maximum value at its vertex. The $x$-coordinate of the vertex is $x = -\\frac{42}{2(-3)} = 7$. Evaluating: $f(7) = -3(49) + 42(7) - 143 = -147 + 294 - 143 = 4$. Because the parabola opens downward, the range is all values $f(x) \\leq 4$. The distractor $f(x) \\geq 4$ reverses the direction of the inequality, incorrectly treating the vertex as a minimum. The distractor $f(x) \\leq -143$ confuses the constant term with the maximum value. The distractor $f(x) \\leq 7$ confuses the $x$-coordinate of the vertex with the maximum output value.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HOBEPR', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'The line $5x - 3y = 21$ is perpendicular to a line that passes through the point $(7, -2)$. If the perpendicular line also passes through the point $(2, k)$, what is the value of $k$?', NULL, $lyceon_json$[{"key":"A","text":"$1$"},{"key":"B","text":"$-5$"},{"key":"C","text":"$5$"},{"key":"D","text":"$-2$"}]$lyceon_json$::jsonb, 'A', NULL, E'Rewriting $5x - 3y = 21$ in slope-intercept form gives $y = \\frac{5}{3}x - 7$, so the slope is $\\frac{5}{3}$. A perpendicular line has slope $-\\frac{3}{5}$. Using the point $(7, -2)$: $y + 2 = -\\frac{3}{5}(x - 7)$, which gives $y = -\\frac{3}{5}x + \\frac{21}{5} - 2 = -\\frac{3}{5}x + \\frac{11}{5}$. Substituting $x = 2$: $y = -\\frac{6}{5} + \\frac{11}{5} = \\frac{5}{5} = 1$. The distractor $-5$ comes from using the reciprocal slope $\\frac{3}{5}$ without negating it, a concept gap about perpendicular slopes. The distractor $5$ results from a sign error, such as incorrectly computing $\\frac{6}{5} + \\frac{11}{5}$ by treating the first term as positive. The distractor $-2$ comes from misreading the question and simply returning the $y$-coordinate of the given point.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IY9FU6', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'A school has 340 students. Each student studies exactly one foreign language: French, German, or Mandarin. The number of students by grade and language is as follows.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2J7APO3', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'The system of equations below has two solutions, $(x_1, y_1)$ and $(x_2, y_2)$. $$y = x^2 - 7x + 11$$ $$y = 3x - 13$$ What is the value of $y_1 + y_2$?', NULL, $lyceon_json$[{"key":"A","text":"$2$"},{"key":"B","text":"$4$"},{"key":"C","text":"$10$"},{"key":"D","text":"$-6$"}]$lyceon_json$::jsonb, 'B', NULL, E'Setting the expressions equal: $x^2 - 7x + 11 = 3x - 13$, which simplifies to $x^2 - 10x + 24 = 0$. Factoring gives $(x - 4)(x - 6) = 0$, so $x_1 = 4$ and $x_2 = 6$. Substituting into $y = 3x - 13$: when $x = 4$, $y = 12 - 13 = -1$; when $x = 6$, $y = 18 - 13 = 5$. Therefore $y_1 + y_2 = -1 + 5 = 4$. The distractor $2$ results from computing $x_2 - x_1 = 6 - 4$ instead of summing the $y$-coordinates. The distractor $10$ comes from summing the $x$-coordinates ($4 + 6$) instead of the $y$-coordinates. The distractor $-6$ results from a sign error when evaluating $y$ at $x = 4$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JOU8BU', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'Which ordered pair $(x, y)$ satisfies the equation $3x + 2y = 26$?', NULL, $lyceon_json$[{"key":"A","text":"$(4, 7)$"},{"key":"B","text":"$(5, 4)$"},{"key":"C","text":"$(2, 9)$"},{"key":"D","text":"$(7, 3)$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $(4, 7)$: $3(4) + 2(7) = 12 + 14 = 26$, which satisfies the equation. Substituting $(5, 4)$: $3(5) + 2(4) = 15 + 8 = 23 \\neq 26$, an arithmetic slip from choosing values that sum close to $26$ but not exactly. Substituting $(2, 9)$: $3(2) + 2(9) = 6 + 18 = 24 \\neq 26$, an equation setup error from swapping coefficient roles. Substituting $(7, 3)$: $3(7) + 2(3) = 21 + 6 = 27 \\neq 26$, partial reasoning that is off by one.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K89KSA', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'grid_in', E'How many integers $x$ satisfy both $\\frac{2x + 5}{3} < 7$ and $4 - 3x \\leq 2x - 11$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'For the first inequality, multiply both sides by $3$: $2x + 5 < 21$. Subtracting $5$ gives $2x < 16$, so $x < 8$. For the second inequality, subtract $2x$ from both sides: $4 - 5x \\leq -11$. Subtracting $4$ gives $-5x \\leq -15$. Dividing by $-5$ and flipping the inequality sign yields $x \\geq 3$. Combining the two results: $3 \\leq x < 8$. The integers satisfying this are $3, 4, 5, 6, 7$, which gives $5$ integers.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KU01CI', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $PQR$, the exterior angle at vertex $R$ measures $139^\\circ$. If angle $P$ measures $73^\\circ$, what is the measure, in degrees, of angle $Q$?', NULL, $lyceon_json$[{"key":"A","text":"$41^\\circ$"},{"key":"B","text":"$66^\\circ$"},{"key":"C","text":"$73^\\circ$"},{"key":"D","text":"$107^\\circ$"}]$lyceon_json$::jsonb, 'B', NULL, E'By the exterior angle theorem, an exterior angle of a triangle equals the sum of the two non-adjacent interior angles. So the exterior angle at $R$ equals $\\angle P + \\angle Q$, giving $139^\\circ = 73^\\circ + \\angle Q$. Solving yields $\\angle Q = 66^\\circ$. The value $41^\\circ$ results from subtracting both the exterior angle and angle $P$ from $180^\\circ$ incorrectly ($180 - 139 = 41$, ignoring angle $P$). The value $73^\\circ$ is simply angle $P$ restated, a misread of what is being asked. The value $107^\\circ$ results from subtracting angle $P$ from $180^\\circ$ instead of from the exterior angle.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KY3QXH', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'mcq', E'A set of 9 data values has a mean of 47 and a median of 43. A tenth value of 67 is added to the set. Which of the following must be true about the new set of 10 values?', NULL, $lyceon_json$[{"key":"A","text":"The new mean is 49 and the new median is greater than 43."},{"key":"B","text":"The new mean is 49 but the new median cannot be determined without knowing all the original values."},{"key":"C","text":"The new mean is 47 and the new median is 43."},{"key":"D","text":"The new mean is 50 and the new median is 43."}]$lyceon_json$::jsonb, 'B', NULL, E'The original sum is $9 \\times 47 = 423$. Adding 67 gives a sum of 490 and a new mean of $\\frac{490}{10} = 49$. For the median of 10 values, we need the average of the 5th and 6th values in the sorted list. The original median of 43 was the 5th of 9 sorted values, but where the new value 67 is inserted depends on the distribution of the other values. The 5th and 6th values in the new sorted list could vary depending on the original data. Therefore the new mean is definitively 49, but the new median cannot be determined without knowing all the original values. The answer claiming both the mean is 49 and the median is greater than 43 makes an unsupported assumption about the median. The answer claiming both remain unchanged ignores that adding a value above the mean changes the mean. The answer claiming the mean is 50 makes an arithmetic error in computing $\\frac{490}{10}$.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MQ5DFD', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'The line of best fit for a set of data points is given by $y = 3.2x + 11$. What is the predicted value of $y$ when $x = 5$?', NULL, $lyceon_json$[{"key":"A","text":"27"},{"key":"B","text":"16.2"},{"key":"C","text":"42.2"},{"key":"D","text":"67"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = 5$ into $y = 3.2x + 11$ gives $y = 3.2(5) + 11 = 16 + 11 = 27$. The answer 16.2 comes from only computing the product $3.2 \\times 5 = 16$ and then appending the digit 2 from the coefficient rather than adding 11. The answer 42.2 results from an arithmetic slip such as computing $3.2 \\times 5$ as 31.2 and then adding 11. The answer 67 comes from computing $(3.2 + 11) \\times 5$ instead of $3.2(5) + 11$, applying the wrong order of operations.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N3ZGYZ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A data set consists of the values 11, 17, 23, 23, and 31. What is the median of this data set?', NULL, $lyceon_json$[{"key":"A","text":"17"},{"key":"B","text":"21"},{"key":"C","text":"23"},{"key":"D","text":"25"}]$lyceon_json$::jsonb, 'C', NULL, E'The five values in ascending order are 11, 17, 23, 23, 31. The median of an odd-numbered set is the middle value, which is the third value: 23. The answer 17 incorrectly selects the second value instead of the third. The answer 21 is the mean of the data set, $(11 + 17 + 23 + 23 + 31)/5 = 105/5 = 21$, not the median. The answer 25 results from incorrectly averaging 23 and 27.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NU0LYE', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'What is the value of $x$ in the equation $\\frac{2(5x - 9)}{3} = 4x + 2$?', NULL, $lyceon_json$[{"key":"A","text":"$-12$"},{"key":"B","text":"$12$"},{"key":"C","text":"$-3$"},{"key":"D","text":"$3$"}]$lyceon_json$::jsonb, 'A', NULL, E'Multiply both sides by $3$: $2(5x - 9) = 3(4x + 2)$. Distribute: $10x - 18 = 12x + 6$. Subtract $10x$ from both sides: $-18 = 2x + 6$. Subtract $6$: $-24 = 2x$, so $x = -12$. The distractor $12$ results from dropping the negative sign when dividing $-24$ by $2$. The distractor $-3$ comes from partial reasoning, such as dividing $-18$ by $6$ without completing the full equation manipulation. The distractor $3$ comes from an arithmetic slip where the student reverses signs during distribution.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NXI5PZ', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'grid_in', E'The expression $\\frac{25x^4 - 49y^6}{5x^2 + 7y^3}$ can be written as $ax^2 + by^3$ for constants $a$ and $b$, provided $5x^2 + 7y^3 \\neq 0$. What is the value of $a - b$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '12', ARRAY['12'], E'The numerator $25x^4 - 49y^6$ is a difference of squares: $25x^4 = (5x^2)^2$ and $49y^6 = (7y^3)^2$. Factoring gives $(5x^2 + 7y^3)(5x^2 - 7y^3)$. Dividing by $(5x^2 + 7y^3)$ yields $5x^2 - 7y^3$, so $a = 5$ and $b = -7$. Therefore $a - b = 5 - (-7) = 12$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2O1KCZ6', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'grid_in', E'A water tank initially contains 197 liters. A drain removes water at a constant rate of 13 liters per minute. A second valve adds water at a constant rate of 4 liters per minute. Both the drain and the valve operate simultaneously. After how many minutes will the tank contain exactly 8 liters?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '21', ARRAY['21'], E'The net rate of water change is $-13 + 4 = -9$ liters per minute. The amount of water after $t$ minutes is modeled by the linear function $W(t) = 197 - 9t$. Setting $W(t) = 8$: $197 - 9t = 8$, so $9t = 189$, giving $t = 21$ minutes.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2O3GYOT', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $g$ is defined by $g(x) = 2x^2 - 7x + 3$. What is the value of $g(5)$?', NULL, $lyceon_json$[{"key":"A","text":"$18$"},{"key":"B","text":"$28$"},{"key":"C","text":"$-12$"},{"key":"D","text":"$53$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = 5$: $g(5) = 2(5)^2 - 7(5) + 3 = 2(25) - 35 + 3 = 50 - 35 + 3 = 18$. The distractor $28$ results from computing $2(25) + 3$ while dropping the $-7(5)$ term and then adding incorrectly. The distractor $-12$ comes from a sign error, computing $-2(25) + 35 + 3$. The distractor $53$ results from computing $2(25) + 3$ without subtracting $7(5)$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OYVZAK', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A researcher wants to determine whether a new fertilizer increases tomato yield. She randomly assigns 50 tomato plants to receive the new fertilizer and 50 tomato plants to receive the standard fertilizer, then measures the yield of each plant after 8 weeks. This study is best described as which of the following?', NULL, $lyceon_json$[{"key":"A","text":"An observational study, because the researcher observed the plants over time"},{"key":"B","text":"A survey, because the researcher collected data from the plants"},{"key":"C","text":"An experiment, because the researcher randomly assigned treatments to the plants"},{"key":"D","text":"An experiment, because the researcher measured the yield of each plant"}]$lyceon_json$::jsonb, 'C', NULL, E'This is an experiment because the researcher randomly assigned treatments (the new fertilizer vs. the standard fertilizer) to the subjects (the plants). Random assignment of treatments is the defining feature of an experiment. Calling it an observational study because the researcher observed the plants confuses observation (data collection) with the observational study design, where no treatment is imposed. Calling it a survey incorrectly applies the term for questionnaire-based data collection to a plant-based study. The option stating it is an experiment because the researcher measured yield identifies measurement as the defining feature, but measurement alone does not make a study an experiment; random assignment of treatments does.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PPE6DF', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'grid_in', E'A cylinder has a radius of $3$ and a height of $14$. The volume of the cylinder is $k\\pi$ cubic units. What is the value of $k$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '126', ARRAY['126'], E'The volume of a cylinder is $V = \\pi r^2 h = \\pi(3)^2(14) = \\pi(9)(14) = 126\\pi$. Since the volume is expressed as $k\\pi$, the value of $k$ is $126$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PXWHL9', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A factory produces 91 bolts every 7 minutes. At this rate, how many bolts does the factory produce in 45 minutes?', NULL, $lyceon_json$[{"key":"A","text":"585"},{"key":"B","text":"637"},{"key":"C","text":"455"},{"key":"D","text":"630"}]$lyceon_json$::jsonb, 'A', NULL, E'The rate is $\\frac{91}{7} = 13$ bolts per minute. In 45 minutes the factory produces $13 \\times 45 = 585$ bolts. The answer 637 results from an arithmetic slip in the multiplication. The answer 455 comes from mistakenly using a rate of about 10 bolts per minute. The answer 630 comes from incorrectly computing $14 \\times 45$, misidentifying the unit rate.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QH225H', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'A town''s population was 12,500 at the start of 2021. By the end of 2021 it had increased by $8\\%$, and by the end of 2022 it had decreased by $5\\%$ from its end-of-2021 value. What was the town''s population at the end of 2022?', NULL, $lyceon_json$[{"key":"A","text":"12,825"},{"key":"B","text":"12,875"},{"key":"C","text":"12,500"},{"key":"D","text":"13,500"}]$lyceon_json$::jsonb, 'A', NULL, E'After an $8\\%$ increase: $12{,}500 \\times 1.08 = 13{,}500$. After a $5\\%$ decrease: $13{,}500 \\times 0.95 = 12{,}825$. The answer 12,875 results from an arithmetic error in the final multiplication. The answer 12,500 reflects the misconception that an increase followed by a decrease of a different percentage returns to the original value. The answer 13,500 reflects only computing the first increase and ignoring the subsequent decrease.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QMTUUY', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'grid_in', E'If $x = 2$ is a solution of the equation $x^3 - 11x^2 + 38x - 40 = 0$, what is the product of the other two solutions?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '20', ARRAY['20'], E'Since $x = 2$ is a root, $(x - 2)$ is a factor. Performing polynomial division or synthetic division: $x^3 - 11x^2 + 38x - 40 = (x - 2)(x^2 - 9x + 20)$. Factoring the quadratic: $x^2 - 9x + 20 = (x - 4)(x - 5)$. The other two solutions are $4$ and $5$, and their product is $4 \\times 5 = 20$. Alternatively, by Vieta''s formulas applied to $x^2 - 9x + 20$, the product of the roots equals the constant term $20$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RO62IE', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $5x^3 \\cdot 9x^4$?', NULL, $lyceon_json$[{"key":"A","text":"$45x^{12}$"},{"key":"B","text":"$14x^7$"},{"key":"C","text":"$45x^7$"},{"key":"D","text":"$45x^{34}$"}]$lyceon_json$::jsonb, 'C', NULL, E'When multiplying monomials, multiply the coefficients and add the exponents: $5 \\cdot 9 = 45$ and $x^3 \\cdot x^4 = x^{3+4} = x^7$, giving $45x^7$. The distractor $45x^{12}$ results from multiplying the exponents instead of adding them. The distractor $14x^7$ results from adding the coefficients instead of multiplying them. The distractor $45x^{34}$ results from concatenating the exponent digits rather than adding them.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TCJG4E', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A trapezoid has parallel bases of length $13$ and $7$ and a height of $6$. What is the area of the trapezoid?', NULL, $lyceon_json$[{"key":"A","text":"$60$"},{"key":"B","text":"$78$"},{"key":"C","text":"$120$"},{"key":"D","text":"$42$"}]$lyceon_json$::jsonb, 'A', NULL, E'The area of a trapezoid is $\\frac{1}{2}(b_1 + b_2) \\times h = \\frac{1}{2}(13 + 7) \\times 6 = \\frac{1}{2}(20)(6) = 60$. The value $78$ results from multiplying only the longer base by the height ($13 \\times 6 = 78$), ignoring the formula. The value $120$ comes from omitting the $\\frac{1}{2}$ factor: $(13 + 7) \\times 6 = 120$. The value $42$ results from multiplying only the shorter base by the height ($7 \\times 6 = 42$).', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UU43L7', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'A right triangle has legs of length $8$ and $15$. What is the length of the hypotenuse?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$17$"},{"key":"C","text":"$23$"},{"key":"D","text":"$289$"}]$lyceon_json$::jsonb, 'B', NULL, E'Using the Pythagorean theorem, $c = \\sqrt{8^2 + 15^2} = \\sqrt{64 + 225} = \\sqrt{289} = 17$. The value $7$ results from subtracting the legs ($15 - 8$) instead of applying the theorem. The value $23$ comes from adding the legs ($8 + 15$) instead of using the theorem. The value $289$ is the square of the hypotenuse, forgetting to take the square root.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VAGGHT', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What is the positive solution of the equation $x^2 + 3x - 40 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$5$"},{"key":"C","text":"$8$"},{"key":"D","text":"$10$"}]$lyceon_json$::jsonb, 'B', NULL, E'Factoring the quadratic: $x^2 + 3x - 40 = (x + 8)(x - 5) = 0$, giving $x = -8$ or $x = 5$. The positive solution is $5$. The distractor $3$ comes from misreading the coefficient of $x$ as a solution. The distractor $8$ comes from taking the absolute value of $-8$ rather than identifying which root is already positive. The distractor $10$ results from an arithmetic slip when checking factor pairs of $-40$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VVXP08', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'The expression $\\frac{3x^3 + 5x^2 - 26x + 11}{3x - 1}$ can be written in the form $ax^2 + bx + c + \\frac{r}{3x - 1}$, where $a$, $b$, $c$, and $r$ are constants. What is the value of $a + b + c + r$?', NULL, $lyceon_json$[{"key":"A","text":"$-2$"},{"key":"B","text":"$-4$"},{"key":"C","text":"$2$"},{"key":"D","text":"$-5$"}]$lyceon_json$::jsonb, 'A', NULL, E'Performing polynomial long division of $3x^3 + 5x^2 - 26x + 11$ by $3x - 1$: first, $3x^3 \\div 3x = x^2$, so $a = 1$. Multiplying $x^2(3x - 1) = 3x^3 - x^2$ and subtracting from the dividend gives $6x^2 - 26x + 11$. Next, $6x^2 \\div 3x = 2x$, so $b = 2$. Multiplying $2x(3x - 1) = 6x^2 - 2x$ and subtracting gives $-24x + 11$. Then $-24x \\div 3x = -8$, so $c = -8$. Multiplying $-8(3x - 1) = -24x + 8$ and subtracting gives the remainder $r = 3$. Therefore $a + b + c + r = 1 + 2 + (-8) + 3 = -2$. The distractor $-4$ results from an arithmetic slip in computing the remainder. The distractor $2$ comes from a sign error on the $c$ term. The distractor $-5$ comes from omitting the remainder in the sum.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W1EY81', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'A sector of a circle with radius $5$ has a central angle of $144^\\circ$. What is the area of the sector?', NULL, $lyceon_json$[{"key":"A","text":"$4\\pi$"},{"key":"B","text":"$10\\pi$"},{"key":"C","text":"$20\\pi$"},{"key":"D","text":"$25\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The area of a sector is $\\frac{\\theta}{360^\\circ} \\times \\pi r^2$. Substituting gives $\\frac{144}{360} \\times \\pi(5)^2 = \\frac{2}{5} \\times 25\\pi = 10\\pi$. The value $4\\pi$ results from an arithmetic error in simplifying the fraction or the multiplication. The value $20\\pi$ comes from using the arc length formula idea ($\\frac{144}{360} \\times 2\\pi r \\times r$, an incorrect hybrid). The value $25\\pi$ is the full circle area, ignoring the sector fraction entirely.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Y5FHO2', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $\\frac{6x^2 - 13x - 28}{2x - 7}$ for $x \\neq \\frac{7}{2}$?', NULL, $lyceon_json$[{"key":"A","text":"$3x + 4$"},{"key":"B","text":"$3x - 4$"},{"key":"C","text":"$3x + 7$"},{"key":"D","text":"$6x + 4$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factoring the numerator: $6x^2 - 13x - 28 = (2x - 7)(3x + 4)$. Verification: $(2x - 7)(3x + 4) = 6x^2 + 8x - 21x - 28 = 6x^2 - 13x - 28$. Dividing by $(2x - 7)$ gives $3x + 4$. The distractor $3x - 4$ comes from a sign error in the constant term during factoring. The distractor $3x + 7$ results from an arithmetic slip when identifying the factor pair. The distractor $6x + 4$ results from failing to divide the leading coefficient properly during the factoring process.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YB7GSO', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A marine biologist captures a random sample of 120 fish from a lake. She tags each fish and releases it back. Two weeks later, she captures a second random sample of 90 fish and finds that 12 of them are tagged. Based on this capture-recapture method, which of the following is the best estimate of the total number of fish in the lake?', NULL, $lyceon_json$[{"key":"A","text":"360"},{"key":"B","text":"600"},{"key":"C","text":"900"},{"key":"D","text":"1080"}]$lyceon_json$::jsonb, 'C', NULL, E'Using the capture-recapture proportion: $\\frac{\\text{tagged in second sample}}{\\text{second sample size}} = \\frac{\\text{total tagged}}{\\text{total population}}$, so $\\frac{12}{90} = \\frac{120}{N}$. Solving gives $N = \\frac{120 \\times 90}{12} = 900$. The value 360 results from computing $120 \\times 90 / 30$, using an incorrect count of tagged fish. The value 600 comes from an arithmetic error such as $120 \\times 90 / 18$. The value 1080 results from multiplying $120 \\times 9$ incorrectly, mishandling the proportion setup.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z7CX87', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In triangle $JKL$, angle $J$ measures $47^\\circ$ and angle $K$ measures $68^\\circ$. What is the measure, in degrees, of angle $L$?', NULL, $lyceon_json$[{"key":"A","text":"$55^\\circ$"},{"key":"B","text":"$65^\\circ$"},{"key":"C","text":"$75^\\circ$"},{"key":"D","text":"$115^\\circ$"}]$lyceon_json$::jsonb, 'B', NULL, E'The sum of the interior angles of a triangle is $180^\\circ$. Therefore, angle $L = 180^\\circ - 47^\\circ - 68^\\circ = 65^\\circ$. The value $55^\\circ$ results from a subtraction error ($180 - 47 - 68$ miscalculated as $55$). The value $75^\\circ$ results from a different arithmetic slip. The value $115^\\circ$ comes from finding the supplement of one angle ($180 - 65$) rather than the angle itself.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZG8THY', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'The function $g$ is defined by $g(x) = -3x + 17$. What is the value of $g(4)$?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$29$"},{"key":"C","text":"$-29$"},{"key":"D","text":"$14$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = 4$: $g(4) = -3(4) + 17 = -12 + 17 = 5$. The distractor $29$ results from treating the coefficient as positive, computing $3(4) + 17 = 29$ instead of $-3(4) + 17$. The distractor $-29$ results from an arithmetic slip where both terms are made negative: $-3(4) - 17 = -29$. The distractor $14$ comes from partial reasoning, computing $17 - 3 = 14$ without multiplying the coefficient by the input.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZJAPOB', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'grid_in', E'If $\\frac{3(2x - 7)}{4} + 5 = \\frac{x}{2}$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '1/4', ARRAY['1/4', '0.25', '.25'], E'Multiply every term by $4$ to clear the denominators: $3(2x - 7) + 20 = 2x$. Distribute on the left: $6x - 21 + 20 = 2x$, which simplifies to $6x - 1 = 2x$. Subtract $2x$ from both sides: $4x - 1 = 0$, so $4x = 1$ and $x = \\frac{1}{4}$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZKJKSW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A shirt originally priced at $\\$74$ is on sale for $\\$55.50$. What is the percent decrease in price?', NULL, $lyceon_json$[{"key":"A","text":"$18.5\\%$"},{"key":"B","text":"$25\\%$"},{"key":"C","text":"$33\\%$"},{"key":"D","text":"$74.3\\%$"}]$lyceon_json$::jsonb, 'B', NULL, E'The decrease is $74 - 55.50 = 18.50$. The percent decrease is $\\frac{18.50}{74} \\times 100 = 25\\%$. The answer $18.5\\%$ confuses the dollar amount of decrease with the percentage. The answer $33\\%$ results from dividing the decrease by the sale price ($\\frac{18.50}{55.50} \\approx 0.333$) instead of the original price. The answer $74.3\\%$ comes from computing $\\frac{55.50}{74} \\times 100$, which gives the fraction of the original price that remains, not the percent decrease.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZR7FL7', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A solid is formed by removing a cone from the interior of a cylinder. The cone and the cylinder share the same circular base with radius $r$ and have the same height $h$, where $h = 2r$. If the volume of the remaining solid is $288\\pi$ cubic units, what is the value of $r$?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$6$"},{"key":"C","text":"$8$"},{"key":"D","text":"$12$"}]$lyceon_json$::jsonb, 'B', NULL, E'The volume of the cylinder is $\\pi r^2 h$ and the volume of the cone is $\\frac{1}{3}\\pi r^2 h$. The remaining volume is $\\pi r^2 h - \\frac{1}{3}\\pi r^2 h = \\frac{2}{3}\\pi r^2 h$. Substituting $h = 2r$ gives $\\frac{2}{3}\\pi r^2(2r) = \\frac{4}{3}\\pi r^3$. Setting this equal to $288\\pi$: $\\frac{4}{3}r^3 = 288$, so $r^3 = 216$, and $r = 6$. The value $4$ results from an arithmetic error when solving the cubic equation. The value $8$ comes from incorrectly setting up the volume difference (for example, omitting the $\\frac{1}{3}$ factor for the cone). The value $12$ results from confusing $r$ with the height $h = 2r$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZSIF69', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'grid_in', E'An investment grows by $12\\%$ in the first year and then declines by $k\\%$ in the second year, ending at exactly $\\$1{,}008$ on an original investment of $\\$1{,}000$. What is the value of $k$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '10', ARRAY['10'], E'After the first year the investment is $1{,}000 \\times 1.12 = 1{,}120$. After the second year, $1{,}120 \\times (1 - k/100) = 1{,}008$. Solving: $1 - k/100 = \\frac{1{,}008}{1{,}120} = 0.9$, so $k/100 = 0.1$ and $k = 10$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW204RCEC', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Marine biologist Kenji Watanabe has spent thirteen years studying cleaner wrasses on coral reefs in the Andaman Sea; his most remarkable finding_______ these small fish can recognize their own reflections, a cognitive ability previously confirmed in only a handful of non-human species.', $lyceon_json$[{"key":"A","text":"finding, these"},{"key":"B","text":"finding; these"},{"key":"C","text":"finding. These"},{"key":"D","text":"finding: these"}]$lyceon_json$::jsonb, 'D', NULL, E'The phrase "his most remarkable finding" is a noun phrase, not an independent clause, and it introduces a specification of what the finding is. A colon is the correct punctuation mark to link a noun phrase to the clause that defines or elaborates it. The option using a colon correctly signals that what follows identifies the finding. A comma after a noun phrase followed by an independent clause produces an ungrammatical construction rather than a standard comma splice (since the first element lacks a verb), and it fails to signal the explanatory relationship. A semicolon is incorrect because it requires independent clauses on both sides, and "his most remarkable finding" has no verb and therefore is not an independent clause. A period is incorrect because it would leave "His most remarkable finding." as a sentence fragment.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20F940Z', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Historian Mariana Vasconcelos has argued that the 1789 Inconfidencia Mineira in colonial Brazil was driven primarily by local tax grievances rather than Enlightenment ideology. Other scholars, however, point to the conspirators'' extensive correspondence with French philosophes as evidence of ideological motivation. __________ Vasconcelos does not deny that the conspirators read Enlightenment texts; she contends that their rhetoric borrowed Enlightenment language to legitimize what were fundamentally economic demands.', E'Historian Mariana Vasconcelos has argued that the 1789 Inconfidencia Mineira in colonial Brazil was driven primarily by local tax grievances rather than Enlightenment ideology. Other scholars, however, point to the conspirators'' extensive correspondence with French philosophes as evidence of ideological motivation. __________ Vasconcelos does not deny that the conspirators read Enlightenment texts; she contends that their rhetoric borrowed Enlightenment language to legitimize what were fundamentally economic demands.', $lyceon_json$[{"key":"A","text":"To be sure,"},{"key":"B","text":"By contrast,"},{"key":"C","text":"In addition,"},{"key":"D","text":"As a result,"}]$lyceon_json$::jsonb, 'A', NULL, E'The third sentence acknowledges a point raised by the opposing scholars (that the conspirators did read Enlightenment texts) before reasserting Vasconcelos''s position that this reading served economic rather than ideological ends. "To be sure," correctly introduces a concessive acknowledgment that sets up the rebuttal in the second half of the sentence. "By contrast," implies the third sentence introduces a wholly opposing viewpoint, but it actually concedes part of the opposing argument before refining Vasconcelos''s original claim. "In addition," suggests an additive relationship, failing to capture the concessive structure of the sentence. "As a result," implies causation, but the third sentence does not follow as a consequence of the scholars'' counterargument; it is Vasconcelos''s nuanced response to it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
