INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25HGI73', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the text, what is the meaning of "tractable"?', E'Nineteenth-century metallurgists discovered that adding small quantities of chromium to iron ore during the smelting process yielded an alloy far more tractable than pure iron. This newfound malleability allowed artisans to hammer the metal into intricate shapes that would have been impossible with the brittle, unyielding iron they had previously relied upon.', $lyceon_json$[{"key":"A","text":"transparent"},{"key":"B","text":"workable"},{"key":"C","text":"volatile"},{"key":"D","text":"luminous"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage clarifies the meaning of "tractable" with the phrase "newfound malleability" and the description of artisans hammering the metal into intricate shapes, indicating the alloy was easy to shape or work with. "Workable" captures this sense of being amenable to manipulation. "Transparent" refers to the ability to see through a material, which is irrelevant to metalworking. "Volatile" means unstable or explosive, which contradicts the controlled shaping described. "Luminous" means glowing or emitting light, which has no connection to the malleability discussed in the passage.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29ON3I4', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'While the fruit bat Rousettus aegyptiacus relies on echolocation to navigate dark caves, it does not produce ultrasonic clicks the way most echolocating bats do. __________ it generates sound by clicking its tongue against the roof of its mouth, creating broadband pulses audible even to human ears.', E'While the fruit bat Rousettus aegyptiacus relies on echolocation to navigate dark caves, it does not produce ultrasonic clicks the way most echolocating bats do. __________ it generates sound by clicking its tongue against the roof of its mouth, creating broadband pulses audible even to human ears.', $lyceon_json$[{"key":"A","text":"Instead,"},{"key":"B","text":"Furthermore,"},{"key":"C","text":"Regardless,"},{"key":"D","text":"For instance,"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that Rousettus aegyptiacus does not use ultrasonic clicks and then describes the alternative method it does use. "Instead," correctly signals this contrast between what is expected and what actually occurs. "Furthermore," incorrectly implies the second sentence adds a similar point rather than presenting a contrasting mechanism. "Regardless," suggests the second sentence proceeds despite an obstacle, but the first sentence presents a factual distinction, not an obstacle. "For instance," implies the second sentence is an example of the first, but it is actually describing a contrasting alternative.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29OXSBH', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'A team of marine biologists at the University of Bergen recently published findings from a seven-year study of fjord ecosystems in western Norway. The researchers discovered that populations of the cold-water coral Lophelia pertusa had declined by nearly 37 percent since 2016, a trend they attribute primarily to rising water temperatures in deep fjord channels. According to the study''s lead author, Karin Eldjarn, the loss of these coral colonies has had cascading effects on other species, including several commercially important fish that rely on the coral structures for shelter during early life stages.', $lyceon_json$[{"key":"A","text":"Lophelia pertusa is a species of cold-water coral that grows exclusively in Norwegian fjords."},{"key":"B","text":"A long-term study found that warming fjord waters have significantly reduced cold-water coral populations, with broader ecological consequences."},{"key":"C","text":"Commercial fishing in Norwegian fjords has been disrupted by the decline of deep-water coral species over the past decade."},{"key":"D","text":"Marine biologists at the University of Bergen are developing new methods for monitoring deep-water ecosystems in Scandinavia, with a particular focus on tracking temperature changes in the deepest fjord channels."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage centers on the finding that warming fjord waters have caused a 37 percent decline in Lophelia pertusa populations, with cascading effects on other species. The option stating that a long-term study found warming waters reduced coral populations with broader ecological consequences captures this main idea. The option about Lophelia pertusa growing exclusively in Norwegian fjords distorts the passage, which never claims exclusivity. The option about commercial fishing disruption overstates the passage''s mention of commercially important fish relying on coral for early-stage shelter. The option about developing new monitoring methods introduces a claim the passage does not make.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BOFPN4', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'While researching a topic, a student has taken the following notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2C5JLK7', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the main idea of the text?', E'Literary scholar Fumiko Arakawa has argued that the narrative structure of Natsume Soseki''s 1914 novel Kokoro is frequently mischaracterized in Western critical traditions. Most anglophone analyses treat the novel''s three-part structure as a linear progression culminating in Sensei''s testament, interpreting the earlier sections as mere prologue. Arakawa contends that this reading flattens the novel''s deliberate structural counterpoint: the narrator''s mundane present-tense observations in Parts One and Two are not subordinate to Sensei''s confession but exist in productive tension with it, creating an irresolvable ambiguity about whether understanding another person is possible at all. Arakawa draws on narratological frameworks developed by Dorrit Cohn to distinguish between the narrator''s external focalization and Sensei''s internal retrospection, arguing that Soseki exploits the gap between these modes to undermine any single interpretive resolution.', $lyceon_json$[{"key":"A","text":"Arakawa challenges the dominant Western reading of Kokoro by arguing that the novel's structure creates an unresolvable tension between two narrative modes rather than a linear progression toward a climactic revelation."},{"key":"B","text":"Arakawa applies Dorrit Cohn's narratological frameworks to demonstrate that Soseki's Kokoro should be classified as an example of internal retrospection rather than external focalization in Japanese literary history."},{"key":"C","text":"Western scholars have generally failed to appreciate the significance of the narrator's present-tense observations in Kokoro because they lack familiarity with Japanese literary conventions of the early twentieth century."},{"key":"D","text":"Arakawa's analysis establishes that Soseki deliberately structured Kokoro to prevent readers from empathizing with Sensei, thereby subverting the conventions of confessional fiction that were prevalent in Japan during the Taisho era."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes Arakawa''s argument that the standard Western reading of Kokoro as a linear progression toward Sensei''s testament is reductive, and that the novel''s structure instead creates a productive, irresolvable tension between the narrator''s external observations and Sensei''s internal confession. The option about Arakawa challenging the dominant reading by identifying unresolvable tension between two narrative modes accurately captures this central argument. The option about classifying Kokoro as internal retrospection rather than external focalization misrepresents Arakawa''s point, which is about the gap between both modes, not a reclassification into one. The option about Western scholars lacking familiarity with Japanese conventions introduces a cause the passage never attributes to the mischaracterization. The option about preventing readers from empathizing with Sensei overstates and distorts the argument, which concerns interpretive ambiguity rather than blocked empathy.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CR2EUT', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The Kola Superdeep Borehole, a Soviet-era scientific drilling project that reached a depth of over twelve kilometers beneath the Kola Peninsula_______ remains the deepest artificial point on Earth, although several other projects have since attempted to surpass its record.', $lyceon_json$[{"key":"A","text":"Peninsula; remains"},{"key":"B","text":"Peninsula remains"},{"key":"C","text":"Peninsula, remains"},{"key":"D","text":"Peninsula. Remains"}]$lyceon_json$::jsonb, 'C', NULL, E'The phrase "a Soviet-era scientific drilling project that reached a depth of over twelve kilometers beneath the Kola Peninsula" is a nonessential appositive set off by commas. Since an opening comma appears before the appositive (after "Borehole"), a closing comma is needed after "Peninsula" to complete the pair. The option providing a comma correctly closes the appositive. A semicolon is incorrect because it would improperly split the sentence''s subject from its verb, and the appositive is not an independent clause. Omitting punctuation entirely leaves the appositive unclosed, creating a grammatical error. A period is incorrect because it would turn the subject and its appositive into a sentence fragment and leave "remains" without a subject.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DWLBYE', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Neither the lead ornithologist nor her four field assistants_______ able to locate the nesting site of the critically endangered spoon-billed sandpiper during the 2024 survey of the coastal wetlands near Kamchatka.', $lyceon_json$[{"key":"A","text":"was"},{"key":"B","text":"is"},{"key":"C","text":"has been"},{"key":"D","text":"were"}]$lyceon_json$::jsonb, 'D', NULL, E'In a "neither...nor" construction, the verb must agree in number with the subject closer to it. Here, the nearer subject is "her four field assistants," which is plural. The option "were" correctly provides a plural past-tense verb. The singular "was" would be correct only if the nearer subject were singular. The singular present-tense "is" fails on both number agreement and tense, since the passage specifies a past event (the 2024 survey). The singular present-perfect "has been" also fails on number agreement with the plural nearer subject and introduces an inappropriate tense for a completed past survey.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2F4WA48', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'In a 2023 paper published in the journal Antiquity, archaeologist Maren Steffensen examined pottery fragments excavated from a Bronze Age settlement in southern Denmark. Steffensen argues that the fragments'' mineral composition indicates they were produced not locally but at workshops nearly 200 kilometers to the southeast, in what is now northern Germany. This finding complicates the prevailing view among scholars that Bronze Age communities in this region were largely self-sufficient in their ceramic production. Steffensen acknowledges, however, that her sample size of 41 fragments from a single site is insufficient to overturn the established model on its own, and she calls for comparative analyses at additional settlements.', $lyceon_json$[{"key":"A","text":"Although Steffensen's pottery analysis challenges the assumption of local ceramic self-sufficiency in Bronze Age Denmark, she recognizes the evidence is too limited to be conclusive."},{"key":"B","text":"Steffensen has definitively proven that Bronze Age communities in southern Denmark imported all of their pottery from workshops in northern Germany."},{"key":"C","text":"The prevailing model of Bronze Age ceramic production in Denmark has been thoroughly discredited by mineral composition analyses of excavated pottery fragments."},{"key":"D","text":"Steffensen's research focuses primarily on identifying the trade routes that Bronze Age communities used to transport finished ceramic goods across long distances between workshops and settlements in northern Europe."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents Steffensen''s finding that certain pottery fragments originated far from the settlement where they were found, which challenges assumptions of local self-sufficiency, but it also notes her acknowledgment that the sample is too small to overturn the established model. The option stating that her analysis challenges the self-sufficiency assumption while recognizing the evidence is limited captures both dimensions. The option claiming she definitively proved all pottery was imported overstates her cautious conclusion. The option about the prevailing model being thoroughly discredited contradicts her explicit acknowledgment of insufficient evidence. The option about identifying trade routes mischaracterizes her research focus, which is about production origin rather than transport logistics.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FQUBDN', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Ecologists studying salt marshes along the coast of Georgia have hypothesized that the invasive grass Phragmites australis outcompetes native cordgrass (Spartina alterniflora) primarily by altering soil chemistry rather than by direct resource competition for sunlight or space. Specifically, the researchers propose that Phragmites root systems release compounds that increase soil salinity in the immediate root zone, creating conditions that native cordgrass cannot tolerate.', $lyceon_json$[{"key":"A","text":"Cordgrass populations decline at similar rates regardless of whether Phragmites is present in shaded or fully sunlit areas of the marsh."},{"key":"B","text":"Phragmites grows taller than cordgrass in laboratory conditions when both species receive identical quantities of water and nutrients."},{"key":"C","text":"Marshes with higher Phragmites density tend to have lower overall biodiversity than marshes dominated by cordgrass."},{"key":"D","text":"Cordgrass populations in Georgia's salt marshes have been declining steadily over the past two decades due to rising sea levels and increased storm activity."}]$lyceon_json$::jsonb, 'A', NULL, E'The hypothesis states that Phragmites outcompetes cordgrass through soil chemistry changes rather than through direct competition for sunlight or space. A finding that cordgrass declines at similar rates regardless of sunlight conditions would weaken the alternative explanation (direct light competition) and thereby support the soil chemistry mechanism. The finding about Phragmites growing taller in laboratory conditions demonstrates a physical advantage but does not address the soil chemistry mechanism. The finding about lower biodiversity in Phragmites-dominated marshes describes a correlation but does not distinguish between the soil chemistry hypothesis and other possible mechanisms. The finding about cordgrass declining due to sea levels and storms introduces entirely different causes unrelated to the hypothesis.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2H21RHX', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1: Ecologist Tomasz Halecki maintains that reintroducing apex predators such as wolves to regions from which they have been extirpated is the single most effective method for restoring degraded ecosystems. Where wolves have returned, Halecki notes, overgrazing by deer has declined, streamside vegetation has recovered, and erosion rates have dropped sharply.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HT4ONR', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text as a whole?', E'Marine biologists have long known that coral reefs support an extraordinary diversity of species. A single reef system in the western Pacific, for instance, may harbor over 1,700 species of fish and 400 species of coral. [underline]Yet despite this abundance, coral ecosystems are remarkably fragile.[/underline] Rising ocean temperatures, acidification, and pollution have caused widespread bleaching events that have decimated reef populations across every major ocean basin.', $lyceon_json$[{"key":"A","text":"It provides a specific example that supports the claim made in the first sentence of the passage."},{"key":"B","text":"It introduces a contrast between the biodiversity of coral reefs and their vulnerability to environmental threats."},{"key":"C","text":"It challenges the methodology that marine biologists have used to study coral reef diversity."},{"key":"D","text":"It summarizes the findings of a long-term research study on coral reef populations conducted across multiple sites in the Pacific Ocean."}]$lyceon_json$::jsonb, 'B', NULL, E'The underlined sentence begins with "Yet despite this abundance," which signals a pivot from the preceding discussion of biodiversity to the fragility of coral ecosystems. It thus introduces a contrast between the richness of reef life and the vulnerability of that life to threats. The choice stating that it provides a specific example is incorrect because the underlined sentence offers no specific data; the specific example (1,700 species of fish, 400 species of coral) appears in the sentence before. The choice about challenging research methodology is incorrect because the passage never questions how biologists study reefs. The choice about summarizing findings of a long-term study is incorrect because no particular study is referenced in the underlined sentence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HUZCWS', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes the relationship between the two texts?', E'Text 1: Literary critic Andrei Volkov argues that the novels of the late nineteenth century increasingly treated urban settings not merely as backdrops but as active forces shaping characters'' psychological states. In Volkov''s reading, the noise, anonymity, and ceaseless motion of the industrial city produced a distinctively modern form of alienation that earlier pastoral fiction could neither depict nor anticipate.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2O0JJ0W', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the text, what is the meaning of "arrest"?', E'The architectural historian Eleanora Voss has argued that the peculiar asymmetry of the Palazzo Morvillo''s facade was not, as earlier scholars assumed, the result of hasty or incompetent construction but rather a deliberate strategy to arrest the viewer''s gaze. By disrupting the expected bilateral symmetry, the architect forced passersby to pause and examine the structure more closely, transforming a routine glance into sustained contemplation.', $lyceon_json$[{"key":"A","text":"prosecute"},{"key":"B","text":"obstruct"},{"key":"C","text":"diminish"},{"key":"D","text":"capture"}]$lyceon_json$::jsonb, 'D', NULL, E'The passage describes the architect''s intent to make passersby pause and examine the structure more closely, transforming a glance into "sustained contemplation." In this context, "arrest" means to seize or hold firmly, and "capture" conveys this sense of seizing and holding attention. "Prosecute" relates to legal proceedings, which is a common meaning of "arrest" in a different context but is entirely wrong for describing the effect on a viewer''s gaze. "Obstruct" means to block or impede, which would imply preventing the gaze rather than holding it. "Diminish" means to reduce or lessen, which contradicts the idea that the asymmetry intensified the viewer''s engagement.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OAKM7H', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Based on the texts, how would the author of Text 1 most likely characterize the approach described in Text 2?', E'Text 1: Cognitive scientist Fumiko Nagai proposes that bilingual children develop executive function advantages not because they possess two language systems per se, but because they must constantly monitor contextual cues to determine which language is appropriate in a given interaction. It is this sustained, context-sensitive monitoring, Nagai argues, rather than the mere storage of two lexicons, that strengthens inhibitory control and cognitive flexibility.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PJJDHR', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'After spending nearly eleven months analyzing sediment cores extracted from Lake Khovsgol in northern Mongolia_______ geochemist Dr. Priya Subramanian concluded that volcanic activity in the region had been significantly more frequent during the late Holocene than researchers had previously estimated.', $lyceon_json$[{"key":"A","text":"Mongolia, geochemist"},{"key":"B","text":"Mongolia; geochemist"},{"key":"C","text":"Mongolia. Geochemist"},{"key":"D","text":"Mongolia geochemist"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence begins with a long introductory adverbial phrase ("After spending nearly eleven months analyzing sediment cores extracted from Lake Khovsgol in northern Mongolia"), which must be followed by a comma before the main clause. The option using a comma correctly sets off this introductory phrase. A semicolon is incorrect because a semicolon joins two independent clauses, and the introductory phrase beginning with "After" is a dependent element, not an independent clause. A period is incorrect for the same reason: it would turn the introductory phrase into a sentence fragment. Omitting punctuation entirely creates a run-on that is difficult to parse.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PM9BKU', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'In 1847, the physician Ignaz Semmelweis noticed that the mortality rate in the maternity ward staffed by medical students was nearly five times higher than in the ward staffed by midwives. He hypothesized that the students, who often came directly from performing autopsies, were carrying infectious material on their hands. When Semmelweis instituted a policy of handwashing with chlorinated lime solution, the mortality rate in the student-staffed ward dropped from 18 percent to under 2 percent. Nevertheless, the medical establishment rejected his findings, and Semmelweis spent years defending his theory against hostile colleagues who dismissed the idea that physicians'' own hands could transmit disease.', $lyceon_json$[{"key":"A","text":"It presents an observation, describes a hypothesis and its successful test, and then notes the unexpected rejection of the results."},{"key":"B","text":"It compares two competing theories about disease transmission and evaluates which one was ultimately vindicated."},{"key":"C","text":"It narrates a physician's career in chronological order and ends with an assessment of his lasting legacy."},{"key":"D","text":"It describes a medical controversy surrounding disease transmission and then offers a balanced analysis of the strongest arguments on both sides of the debate."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage follows a clear sequence: Semmelweis observes a disparity in mortality rates, proposes a hypothesis about infectious material, tests it with a handwashing intervention that dramatically reduces mortality, and then faces rejection from the medical community. The choice stating the text presents an observation, a hypothesis with its successful test, and the unexpected rejection accurately captures this structure. The choice about comparing two competing theories is wrong because only Semmelweis''s hypothesis is presented; no rival theory is described. The choice about narrating a career in chronological order overstates the scope, as the passage covers one specific episode rather than an entire career, and no assessment of lasting legacy appears. The choice about offering a balanced analysis is incorrect because the passage does not present arguments from the opposing side in any detail or treat both positions as equally valid.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QF5RPR', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'Entomologist Riya Sengupta has been studying the foraging behavior of Asian giant hornets (Vespa mandarinia) in mountainous regions of Yunnan Province. Sengupta observed that hornets in colonies located above 2,400 meters in elevation foraged almost exclusively on beetles and moth larvae, while hornets in colonies below 1,100 meters consumed a diverse diet that included fruit, tree sap, and other insect species in roughly equal proportions. Sengupta notes that beetle and moth larvae are far more calorie-dense per gram than fruit or sap, suggesting that the high-elevation hornets'' dietary specialization ________', $lyceon_json$[{"key":"A","text":"may be an adaptation to the greater energy demands of foraging in colder, thinner-air environments."},{"key":"B","text":"is likely a consequence of human agricultural activity reducing fruit availability at higher altitudes."},{"key":"C","text":"indicates that beetles and moth larvae are easier to locate in mountainous terrain than in lowland forests."},{"key":"D","text":"demonstrates that Asian giant hornets prefer calorie-dense prey whenever such prey is available regardless of elevation."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that high-elevation hornets specialize in calorie-dense prey while low-elevation hornets eat a varied diet, and it notes that the specialized prey is more calorie-dense. The logical completion connects the calorie density of the prey to the energy challenges of the high-elevation environment. The option about human agricultural activity introduces a factor the passage never mentions. The option about beetles being easier to locate at high elevations makes a claim about prey availability that the passage does not support. The option about hornets preferring calorie-dense prey regardless of elevation contradicts the observation that low-elevation hornets eat a diverse diet including less calorie-dense items.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RCNPTR', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the purpose of the text?', E'The prevailing account of the Haitian Revolution emphasizes the ideological influence of the French Revolution, casting the enslaved population''s revolt as an extension of Enlightenment principles to the Caribbean. Historian Carolyn Dubois, however, has drawn attention to the Vodou spiritual gatherings that preceded the 1791 uprising, arguing that these ceremonies provided both the organizational infrastructure and the motivating cosmology for the rebellion. Dubois does not deny the relevance of Enlightenment thought but insists that foregrounding it to the exclusion of indigenous spiritual traditions reproduces the very Eurocentric framing the revolution sought to overthrow.', $lyceon_json$[{"key":"A","text":"To refute the claim that the French Revolution had any meaningful influence on political movements in the Caribbean."},{"key":"B","text":"To compare the relative military effectiveness of two different organizational strategies used during the Haitian Revolution."},{"key":"C","text":"To demonstrate that spiritual practices were more historically significant than political ideologies in shaping revolutionary movements worldwide."},{"key":"D","text":"To present a historian's argument that a standard interpretation of a historical event is incomplete because it overlooks an important indigenous dimension."}]$lyceon_json$::jsonb, 'D', NULL, E'The passage introduces the prevailing Enlightenment-centered account and then presents Dubois''s counterargument that Vodou ceremonies were a crucial but overlooked factor. Dubois explicitly does not deny the relevance of Enlightenment thought but argues that excluding indigenous traditions is incomplete and Eurocentric. The choice about presenting a historian''s argument that a standard interpretation is incomplete because it overlooks an indigenous dimension accurately reflects this nuanced position. The choice about refuting French Revolutionary influence overstates Dubois''s claim, since the passage explicitly says she does not deny the relevance of Enlightenment thought. The choice about comparing military effectiveness is wrong because the passage discusses organizational infrastructure and motivating cosmology, not military strategy. The choice about demonstrating that spiritual practices were more significant worldwide extends far beyond the passage, which addresses only the Haitian Revolution and does not claim global superiority of spiritual practices over political ideologies.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TBZWVA', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which finding, if true, would most directly weaken the claim made in the text?', E'Agricultural economist Tereza Novakova has argued that small-scale organic farms in the Czech Republic achieve lower per-hectare crop yields than conventional farms primarily because organic farmers lack access to the same quality of technical advisory services, not because organic methods are inherently less productive. Novakova points to data showing that organic farms whose operators participated in government-funded agronomic training programs closed roughly 80 percent of the yield gap with comparable conventional operations within three growing seasons.', $lyceon_json$[{"key":"A","text":"Organic farms in neighboring Slovakia that participated in similar training programs showed yield improvements of only 12 percent relative to conventional farms over the same period."},{"key":"B","text":"Conventional farms in the Czech Republic receive substantially more government funding for infrastructure improvements than organic farms do."},{"key":"C","text":"A nationwide survey found that Czech organic farmers are, on average, younger and more formally educated in agricultural science than their conventional counterparts."},{"key":"D","text":"The government-funded training programs Novakova cites were available only to organic farms with more than 50 hectares of cultivable land, excluding the majority of small-scale operations."}]$lyceon_json$::jsonb, 'C', NULL, E'Novakova''s claim is that the yield gap exists primarily because organic farmers lack access to quality technical advisory services. A finding that organic farmers are on average younger and more formally educated in agricultural science than conventional farmers would undermine the premise that organic farmers are at a knowledge or advisory disadvantage, thus weakening Novakova''s explanation. The finding about Slovakian farms showing only modest improvements addresses a different country and does not directly target Novakova''s causal claim about advisory access. The finding about conventional farms receiving more government infrastructure funding supports rather than weakens the notion that organic farms face systemic disadvantages. The finding about program eligibility restrictions would limit the applicability of Novakova''s supporting evidence but does not address her core claim about advisory access as the primary cause of the yield gap.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VTT81M', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Cognitive psychologist Daan Veldhuis conducted a study in which 128 participants were shown a series of abstract visual patterns and asked to identify which patterns belonged to a category defined by a rule the participants were not told. Participants who received immediate feedback after each classification attempt (being told whether their guess was correct) achieved an average accuracy of 74 percent by the final block of trials. A second group received delayed feedback, learning the correctness of each guess only after completing a set of 20 classification attempts. This group achieved an average accuracy of 81 percent by the final block. Veldhuis notes that the delayed-feedback group reported significantly higher levels of frustration during the task but proposes that the superior performance of this group may be attributable to the fact that ________', $lyceon_json$[{"key":"A","text":"delayed feedback forced participants to develop and test their own internal hypotheses about the category rule, leading to deeper encoding of the rule's structure than the immediate correction provided by instant feedback."},{"key":"B","text":"participants in the delayed-feedback group were inherently more motivated to succeed at the task than those in the immediate-feedback group, as evidenced by their willingness to tolerate higher frustration levels."},{"key":"C","text":"the abstract visual patterns used in the study were simple enough that feedback timing had no meaningful effect on participants' ability to learn the underlying category rule."},{"key":"D","text":"immediate feedback caused participants to rely on memorizing individual pattern-answer pairs rather than on inferring any general rule, which would have produced accuracy rates well below 50 percent in the final block."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that delayed feedback led to higher accuracy despite greater frustration, and asks for an explanation. The option about delayed feedback forcing participants to develop internal hypotheses provides a cognitive mechanism that logically connects the delay to deeper learning of the rule''s structure. The option about the delayed-feedback group being inherently more motivated confuses a result of the experimental condition (frustration tolerance) with a pre-existing trait, and the groups were presumably randomly assigned. The option claiming patterns were simple enough that feedback timing had no meaningful effect directly contradicts the study''s own finding of a 7-percentage-point accuracy difference. The option about immediate feedback causing memorization of individual pairs overstates the case, since the immediate-feedback group still achieved 74 percent accuracy, which is far above the below-50-percent level this option predicts.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2X2KY5Q', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the text, what is the meaning of "rudimentary"?', E'When the first permanent European settlements were established along the coast of present-day Virginia in the early seventeenth century, the colonists constructed rudimentary shelters from whatever timber and thatch they could gather. These crude dwellings offered minimal protection against the harsh winters, and many settlers perished before more substantial structures could be erected.', $lyceon_json$[{"key":"A","text":"portable"},{"key":"B","text":"ornamental"},{"key":"C","text":"basic"},{"key":"D","text":"subterranean"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage describes shelters that were "crude" and offered "minimal protection," indicating they were simple and unsophisticated. The word "basic" captures this meaning of being elementary and lacking refinement. "Portable" implies the shelters could be moved, which contradicts the idea of permanent settlements. "Ornamental" means decorative, which is the opposite of crude and minimal. "Subterranean" means underground, which contradicts the description of shelters built from timber and thatch.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Y0BI74', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Sociologist Amara Okafor examined municipal water-pricing structures in 14 mid-sized cities across three West African countries between 2017 and 2022. She found that cities using inclining block tariffs, in which the per-liter price rises as household consumption increases, reduced average residential water use by 19 percent compared with cities using flat-rate pricing. However, Okafor also found that in the five cities where inclining block tariffs were implemented, the reduction in water use was concentrated almost entirely among households in the top two income quintiles. Households in the bottom three quintiles showed negligible changes in consumption. Okafor concludes that inclining block tariffs are effective conservation tools but that their effectiveness ________', $lyceon_json$[{"key":"A","text":"depends on the ability of wealthier households to absorb the financial consequences of higher-tier pricing, while poorer households may already consume too little water for the tariff structure to influence their behavior."},{"key":"B","text":"is undermined by the tendency of municipal governments to set the base-tier price too high, which discourages water use among all income groups equally and prevents the tiered pricing structure from producing the differentiated consumption patterns that policymakers intended."},{"key":"C","text":"could be improved by replacing the block tariff structure with a flat-rate system that charges all households the same price per liter regardless of consumption volume."},{"key":"D","text":"stems primarily from the psychological impact of receiving an itemized water bill rather than from the actual financial cost of consuming additional liters of water."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that consumption reductions occurred only among wealthier households, while poorer households showed negligible changes. The logical completion explains this pattern: wealthier households can absorb higher-tier costs and adjust their consumption downward, whereas poorer households likely already consume so little that they never reach the higher pricing tiers. The option about base-tier prices being too high contradicts the finding that reductions were not uniform across income groups. The option about replacing block tariffs with flat-rate pricing contradicts the passage''s finding that block tariffs did produce conservation benefits. The option about psychological impact of itemized billing introduces a mechanism the passage never discusses and does not explain the income-differentiated pattern.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YJTYFY', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'By the time the conservation team arrived at the remote wetland site in March 2024, prolonged drought conditions_______ the water level by nearly two meters, exposing sediment layers that had not been visible in over a century.', $lyceon_json$[{"key":"A","text":"reduced"},{"key":"B","text":"have reduced"},{"key":"C","text":"were reducing"},{"key":"D","text":"had reduced"}]$lyceon_json$::jsonb, 'D', NULL, E'The construction "by the time [past-tense event]" signals that another action was completed before that past event, which requires the past perfect tense. The option "had reduced" correctly places the drought''s effect (reducing the water level) before the team''s arrival, both of which occurred in the past. The simple past "reduced" fails to establish the sequence of events required by "by the time" and produces a non-standard construction. The present perfect "have reduced" is incorrect because the entire narrative is set in the past and the present perfect anchors an action to the present moment. The past progressive "were reducing" indicates an ongoing action at a point in the past but does not convey the completed-before-another-past-event relationship that "by the time" demands.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZAGXJQ', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The collection of rare volcanic minerals displayed in the geological museum in Reykjavik_______ researchers and enthusiasts from over thirty countries each year.', $lyceon_json$[{"key":"A","text":"attract"},{"key":"B","text":"have attracted"},{"key":"C","text":"attracts"},{"key":"D","text":"are attracting"}]$lyceon_json$::jsonb, 'C', NULL, E'The subject of the sentence is "collection," a singular noun. The intervening prepositional phrases "of rare volcanic minerals" and "displayed in the geological museum in Reykjavik" do not change the number of the subject. A singular subject requires a singular verb. The option "attracts" correctly provides a third-person singular present-tense verb. The bare plural form "attract" does not agree with the singular subject. The plural auxiliary "have attracted" incorrectly treats "minerals" as the subject. Similarly, "are attracting" uses the plural auxiliary "are," which fails to agree with the singular "collection."', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZWSBAZ', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'A team of marine geologists studying the Mariana Trench discovered that serpentinite mud volcanoes on the Pacific plate release methane and hydrogen at rates far exceeding previous estimates. __________ these gases support thriving chemosynthetic microbial communities at depths where photosynthesis is impossible, suggesting that similar geological processes could sustain life on other planetary bodies.', E'A team of marine geologists studying the Mariana Trench discovered that serpentinite mud volcanoes on the Pacific plate release methane and hydrogen at rates far exceeding previous estimates. __________ these gases support thriving chemosynthetic microbial communities at depths where photosynthesis is impossible, suggesting that similar geological processes could sustain life on other planetary bodies.', $lyceon_json$[{"key":"A","text":"Nevertheless,"},{"key":"B","text":"Crucially,"},{"key":"C","text":"In other words,"},{"key":"D","text":"On the other hand,"}]$lyceon_json$::jsonb, 'B', NULL, E'The second sentence builds on the discovery by highlighting a significant implication: the gases sustain microbial life and may indicate the potential for life elsewhere. "Crucially," correctly signals that this next point is an especially important consequence of the finding. "Nevertheless," incorrectly implies a concession or contrast, but the second sentence extends the first rather than contradicting it. "In other words," suggests a restatement of the same idea, but the second sentence introduces new information about the biological significance. "On the other hand," signals a contrasting perspective, which does not fit because the second sentence presents a consequence, not an opposing viewpoint.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-09-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-09-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
